<?php
/** Plugin Name: TEMP PS S1736j dydžių katalogas v1.3 (1 dry+skaičius / 2 deploy / 3 patikra / 9 atstato) */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1736j'])) return;
  $f=$_GET['ps_s1736j']; @set_time_limit(250); $r=['v'=>'S1736j','faze'=>$f];
  $fn='petshop-dydziai-katalogas.php'; $fp=WPMU_PLUGIN_DIR.'/'.$fn; $OLD='878ff6c4d90b0af4462940ada0ccd3a0'; $NEW='f210053482f5c2fe1030b69300c75a12';
  $ARCH=dirname(rtrim(ABSPATH,'/')).'/ps-archyvas'; $bak=$ARCH.'/'.$fn.'.bak_s1736';
  $get=function($u){ $x=wp_remote_get($u,['timeout'=>40,'sslverify'=>false,'redirection'=>2,'headers'=>['Cookie'=>'ps_js=1']]); if(is_wp_error($x)) return ['ERR '.$x->get_error_message(),'']; return [wp_remote_retrieve_response_code($x),wp_remote_retrieve_body($x)]; };
  $skaicius=function() use($get){ $u=add_query_arg('ps_hb',time().rand(100,999),get_term_link(91,'product_cat')); list($c,$h)=$get($u); $rc=''; if(preg_match('~woocommerce-result-count[^>]*>(.*?)</p>~s',$h,$m)) $rc=trim(wp_strip_all_tags($m[1])); return ['url'=>$u,'http'=>$c,'rezultatai'=>preg_replace('/\s+/',' ',$rc)]; };
  try{
    if($f==='1'){ $r['live']=md5_file($fp); $r['live_ok']=$r['live']===$OLD; $nc=gzuncompress(base64_decode('')); $r['new_ok']=md5($nc)===$NEW; try{ token_get_all($nc,TOKEN_PARSE); $r['tok']=true; }catch(Throwable $e){ $r['tok']=$e->getMessage(); } $r['pries']=$skaicius(); }
    if($f==='2'){ $live=md5_file($fp); $nc=gzuncompress(base64_decode('')); $ok=true; try{ token_get_all($nc,TOKEN_PARSE); }catch(Throwable $e){ $ok=false; }
      if($live!==$OLD||md5($nc)!==$NEW||!$ok){ $r['STOP']=['live'=>$live,'tok'=>$ok]; }
      else{ if(!file_exists($bak)) copy($fp,$bak); $r['bak']=md5_file($bak); file_put_contents($fp,$nc); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['irasyta']=md5_file($fp);
        $x=wp_remote_get(home_url('/?ps_hb='.time()),['timeout'=>25,'sslverify'=>false,'redirection'=>0]); $r['hb']=is_wp_error($x)?'ERR':wp_remote_retrieve_response_code($x);
        if(!is_int($r['hb'])||$r['hb']>=500){ copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['ATSTATYTA']=md5_file($fp); }
        else{ // kešas: DP kategorijos katalogas (su puslapiais)
          $path=trim(wp_parse_url(get_term_link(91,'product_cat'),PHP_URL_PATH),'/'); $dir=WP_CONTENT_DIR.'/cache/supercache/'.wp_parse_url(home_url(),PHP_URL_HOST).'/'.$path;
          $r['kesas_dir']=$dir; $r['kesas_buvo']=is_dir($dir);
          if(is_dir($dir) && function_exists('prune_super_cache')){ prune_super_cache($dir,true); } elseif(is_dir($dir)){ $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST); foreach($it as $x2){ $x2->isDir()?@rmdir($x2->getPathname()):@unlink($x2->getPathname()); } @rmdir($dir); }
          $r['kesas_liko']=is_dir($dir)?count(glob($dir.'/*')):0; } } }
    if($f==='3'){ $r['live_ok']=md5_file($fp)===$NEW; $r['po']=$skaicius();
      // kontrolė: gamintojo psl. ir parduotuvė nepakito (vienai šeimai viena kortelė)
      $b=get_term_by('slug','exclusion','product_brand'); if($b){ list($c,$h)=$get(add_query_arg('ps_hb',time(),get_term_link($b))); if(preg_match('~woocommerce-result-count[^>]*>(.*?)</p>~s',$h,$m)) $r['exclusion']=preg_replace('/\s+/',' ',trim(wp_strip_all_tags($m[1]))); } }
    if($f==='9'){ if(file_exists($bak)){ copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['atstatyta']=md5_file($fp); } }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
}, 1);
